source_texts.configuration_overlay:
import sys


def main():
    lines = sys.stdin.read().splitlines()
    index = 0
    count = int(lines[index])
    index += 1
    configuration = {}
    for _ in range(count):
        key, value = lines[index].split("=", 1)
        index += 1
        configuration[key] = value

    overlay_count = int(lines[index])
    index += 1
    for _ in range(overlay_count):
        key, value = lines[index].split("=", 1)
        index += 1
        if value == "DELETE":
            configuration.pop(key, None)
        else:
            configuration[key] = value

    print(";".join(f"{key}={configuration[key]}" for key in sorted(configuration)))


if __name__ == "__main__":
    main()

source_texts.meeting_schedule:
import sys


def main():
    lines = sys.stdin.read().splitlines()
    count = int(lines[0])
    schedules = {}
    accepted_titles = []
    rejected = 0

    for line in lines[1:1 + count]:
        room, start_text, end_text, title = line.split("|", 3)
        start = int(start_text)
        end = int(end_text)
        bookings = schedules.setdefault(room, [])
        if any(start < booked_end and end > booked_start for booked_start, booked_end in bookings):
            rejected += 1
        else:
            bookings.append((start, end))
            accepted_titles.append(title)

    print(f"{','.join(accepted_titles)}|rejected={rejected}")


if __name__ == "__main__":
    main()

source_texts.contact_merge:
import sys


def main():
    lines = sys.stdin.read().splitlines()
    count = int(lines[0])
    contacts = {}

    for line in lines[1:1 + count]:
        email, name, city = line.split("|", 2)
        contacts[email] = (name, city)

    output = ",".join(
        f"{email}:{contacts[email][0]}@{contacts[email][1]}" for email in sorted(contacts)
    )
    print(f"{output}|unique={len(contacts)}")


if __name__ == "__main__":
    main()

source_texts.ticket_workflow:
import sys


def main():
    lines = sys.stdin.read().splitlines()
    index = 0
    ticket_count = int(lines[index])
    index += 1
    tickets = {}
    for _ in range(ticket_count):
        ticket_id, priority_text, state = lines[index].split("|", 2)
        index += 1
        tickets[ticket_id] = [int(priority_text), state]

    command_count = int(lines[index])
    index += 1
    for _ in range(command_count):
        ticket_id, action = lines[index].split("|", 1)
        index += 1
        if ticket_id not in tickets:
            continue
        if action == "close":
            tickets[ticket_id][1] = "closed"
        elif action == "reopen":
            tickets[ticket_id][1] = "open"
        elif action == "escalate":
            tickets[ticket_id][0] = min(5, tickets[ticket_id][0] + 1)

    open_tickets = sorted(
        ((ticket_id, values[0]) for ticket_id, values in tickets.items() if values[1] == "open"),
        key=lambda item: (-item[1], item[0]),
    )
    print(",".join(f"{ticket_id}:{priority}" for ticket_id, priority in open_tickets))


if __name__ == "__main__":
    main()

