use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let n: usize = lines.next().unwrap().parse().unwrap();
    let mut contacts: BTreeMap<String, (String, String)> = BTreeMap::new();
    for _ in 0..n {
        let parts: Vec<&str> = lines.next().unwrap().split('|').collect();
        contacts.insert(parts[0].to_string(), (parts[1].to_string(), parts[2].to_string()));
    }
    let output = contacts.iter().map(|(email, (name, city))| format!("{email}:{name}@{city}")).collect::<Vec<_>>().join(",");
    println!("{output}|unique={}", contacts.len());
}

sources.file_backed_notes:
use std::fs;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let title = lines.next().unwrap_or("");
    let n: usize = lines.next().unwrap().parse().unwrap();
    let notes: Vec<&str> = (0..n).map(|_| lines.next().unwrap_or("")).collect();
    let mut contents = String::new();
    contents.push_str(title);
    contents.push('\n');
    for note in &notes {
        contents.push_str(note);
        contents.push('\n');
    }
    fs::write("file_backed_notes.txt", contents).unwrap();
    let saved = fs::read_to_string("file_backed_notes.txt").unwrap();
    let mut saved_lines = saved.lines();
    let saved_title = saved_lines.next().unwrap_or("");
    let saved_notes: Vec<&str> = (0..n).map(|_| saved_lines.next().unwrap_or("")).collect();
    let nonempty = saved_notes.iter().filter(|line| !line.is_empty()).count();
    let characters: usize = saved_notes.iter().map(|line| line.len()).sum();
    println!("{saved_title}|{n}|{nonempty}|{characters}");
}

sources.invoice_rollup:
use std::collections::BTreeMap;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let customer = lines.next().unwrap_or("");
    let n: usize = lines.next().unwrap().parse().unwrap();
    let mut categories: BTreeMap<String, u128> = BTreeMap::new();
    let mut subtotal: u128 = 0;
    for _ in 0..n {
        let parts: Vec<&str> = lines.next().unwrap().split('|').collect();
        let quantity: u128 = parts[1].parse().unwrap();
        let price: u128 = parts[2].parse().unwrap();
        let amount = quantity * price;
        subtotal += amount;
        *categories.entry(parts[0].to_string()).or_default() += amount;
    }
    let totals = categories.iter().map(|(category, amount)| format!("{category}:{amount}")).collect::<Vec<_>>().join(",");
    println!("{customer}|{subtotal}|{totals}");
}

sources.meeting_schedule:
use std::collections::HashMap;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let n: usize = lines.next().unwrap().parse().unwrap();
    let mut rooms: HashMap<String, Vec<(i64, i64)>> = HashMap::new();
    let mut accepted = Vec::new();
    let mut rejected = 0;
    for _ in 0..n {
        let parts: Vec<&str> = lines.next().unwrap().split('|').collect();
        let start: i64 = parts[1].parse().unwrap();
        let end: i64 = parts[2].parse().unwrap();
        let bookings = rooms.entry(parts[0].to_string()).or_default();
        if bookings.iter().any(|&(old_start, old_end)| start < old_end && old_start < end) {
            rejected += 1;
        } else {
            bookings.push((start, end));
            accepted.push(parts[3].to_string());
        }
    }
    println!("{}|rejected={rejected}", accepted.join(","));
}

