use std::collections::BTreeMap;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let n: usize = lines.next().unwrap().parse().unwrap();
    let mut shipments: BTreeMap<String, String> = BTreeMap::new();
    for _ in 0..n {
        let (id, state) = lines.next().unwrap().split_once('|').unwrap();
        shipments.insert(id.to_string(), state.to_string());
    }
    let m: usize = lines.next().unwrap().parse().unwrap();
    let mut invalid = 0;
    for _ in 0..m {
        let (id, action) = lines.next().unwrap().split_once('|').unwrap();
        if let Some(state) = shipments.get_mut(id) {
            let next = match (state.as_str(), action) {
                ("created", "pack") => Some("packed"),
                ("packed", "ship") => Some("shipped"),
                ("shipped", "deliver") => Some("delivered"),
                _ => None,
            };
            if let Some(next_state) = next {
                *state = next_state.to_string();
            } else {
                invalid += 1;
            }
        } else {
            invalid += 1;
        }
    }
    let output = shipments.iter().map(|(id, state)| format!("{id}:{state}")).collect::<Vec<_>>().join(",");
    println!("{output}|invalid={invalid}");
}

sources.ticket_workflow:
use std::collections::HashMap;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let n: usize = lines.next().unwrap().parse().unwrap();
    let mut tickets: HashMap<String, (u8, String)> = HashMap::new();
    for _ in 0..n {
        let parts: Vec<&str> = lines.next().unwrap().split('|').collect();
        tickets.insert(parts[0].to_string(), (parts[1].parse().unwrap(), parts[2].to_string()));
    }
    let m: usize = lines.next().unwrap().parse().unwrap();
    for _ in 0..m {
        let (id, action) = lines.next().unwrap().split_once('|').unwrap();
        if let Some((priority, state)) = tickets.get_mut(id) {
            match action {
                "close" => *state = "closed".to_string(),
                "reopen" => *state = "open".to_string(),
                "escalate" => *priority = (*priority + 1).min(5),
                _ => {}
            }
        }
    }
    let mut open: Vec<(&String, &u8)> = tickets.iter().filter_map(|(id, (priority, state))| (state == "open").then_some((id, priority))).collect();
    open.sort_by(|(id_a, priority_a), (id_b, priority_b)| priority_b.cmp(priority_a).then_with(|| id_a.cmp(id_b)));
    println!("{}", open.iter().map(|(id, priority)| format!("{id}:{priority}")).collect::<Vec<_>>().join(","));
}

