source_texts.configuration_overlay:
import sys


def main():
    lines = sys.stdin.read().splitlines()
    position = 0

    count = int(lines[position])
    position += 1
    configuration = {}
    for _ in range(count):
        key, value = lines[position].split("=", 1)
        position += 1
        configuration[key] = value

    overlay_count = int(lines[position])
    position += 1
    for _ in range(overlay_count):
        key, value = lines[position].split("=", 1)
        position += 1
        if value == "DELETE":
            configuration.pop(key, None)
        else:
            configuration[key] = value

    print(";".join(f"{key}={configuration[key]}" for key in sorted(configuration)))


if __name__ == "__main__":
    main()

source_texts.meeting_schedule:
import sys


def main():
    lines = sys.stdin.read().splitlines()
    count = int(lines[0])
    schedules = {}
    accepted = []
    rejected = 0

    for line in lines[1:count + 1]:
        room, start_text, end_text, title = line.split("|", 3)
        start = int(start_text)
        end = int(end_text)
        bookings = schedules.setdefault(room, [])
        if any(start < booked_end and booked_start < end
               for booked_start, booked_end in bookings):
            rejected += 1
        else:
            bookings.append((start, end))
            accepted.append(title)

    print(f"{','.join(accepted)}|rejected={rejected}")


if __name__ == "__main__":
    main()

source_texts.ticket_workflow:
import sys


def main():
    lines = sys.stdin.read().splitlines()
    position = 0
    ticket_count = int(lines[position])
    position += 1
    tickets = {}

    for _ in range(ticket_count):
        ticket_id, priority, state = lines[position].split("|")
        position += 1
        tickets[ticket_id] = [int(priority), state]

    command_count = int(lines[position])
    position += 1
    for _ in range(command_count):
        ticket_id, action = lines[position].split("|")
        position += 1
        if ticket_id not in tickets:
            continue
        if action == "close":
            tickets[ticket_id][1] = "closed"
        elif action == "reopen":
            tickets[ticket_id][1] = "open"
        elif action == "escalate":
            tickets[ticket_id][0] = min(5, tickets[ticket_id][0] + 1)

    open_tickets = [
        (ticket_id, priority)
        for ticket_id, (priority, state) in tickets.items()
        if state == "open"
    ]
    open_tickets.sort(key=lambda ticket: (-ticket[1], ticket[0]))
    print(",".join(f"{ticket_id}:{priority}"
                   for ticket_id, priority in open_tickets))


if __name__ == "__main__":
    main()

