use std::collections::HashMap;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let n: usize = lines.next().unwrap_or("0").trim().parse().unwrap();
    let mut tickets: HashMap<String, (u8, bool)> = HashMap::new();
    for _ in 0..n {
        let fields: Vec<&str> = lines.next().unwrap_or("").split('|').collect();
        tickets.insert(fields[0].to_string(), (fields[1].parse().unwrap(), fields[2] == "open"));
    }
    let m: usize = lines.next().unwrap_or("0").trim().parse().unwrap();
    for _ in 0..m {
        let (id, action) = lines.next().unwrap_or("").split_once('|').unwrap();
        if let Some((priority, open)) = tickets.get_mut(id) {
            match action {
                "close" => *open = false,
                "reopen" => *open = true,
                "escalate" => *priority = (*priority + 1).min(5),
                _ => {}
            }
        }
    }
    let mut open: Vec<_> = tickets.into_iter().filter(|(_, (_, is_open))| *is_open).collect();
    open.sort_by(|a, b| b.1.0.cmp(&a.1.0).then_with(|| a.0.cmp(&b.0)));
    println!("{}", open.iter().map(|(id, (p, _))| format!("{id}:{p}")).collect::<Vec<_>>().join(","));
}

