use std::fs;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let normalized = input.replace("\r\n", "\n");
    let mut lines = normalized.split('\n');
    let title = lines.next().unwrap_or("").to_string();
    let n: usize = lines.next().unwrap_or("0").trim().parse().unwrap();
    let notes: Vec<String> = (0..n).map(|_| lines.next().unwrap_or("").to_string()).collect();
    let mut contents = String::new();
    contents.push_str(&title);
    contents.push('\n');
    for note in &notes {
        contents.push_str(note);
        contents.push('\n');
    }
    fs::write("file_backed_notes.txt", contents).unwrap();
    let stored = fs::read_to_string("file_backed_notes.txt").unwrap();
    let mut stored_lines = stored.split_terminator('\n');
    let stored_title = stored_lines.next().unwrap_or("");
    let stored_notes: Vec<&str> = stored_lines.take(n).collect();
    let nonempty = stored_notes.iter().filter(|line| !line.is_empty()).count();
    let characters: usize = stored_notes.iter().map(|line| line.chars().count()).sum();
    println!("{stored_title}|{n}|{nonempty}|{characters}");
}

