fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let n: usize = lines.next().unwrap_or("0").trim().parse().unwrap();
    let mut schedules: HashMap<String, Vec<(i64, i64)>> = HashMap::new();
    let mut accepted = Vec::new();
    let mut rejected = 0;
    for _ in 0..n {
        let fields: Vec<&str> = lines.next().unwrap_or("").split('|').collect();
        let start: i64 = fields[1].parse().unwrap();
        let end: i64 = fields[2].parse().unwrap();
        let bookings = schedules.entry(fields[0].to_string()).or_default();
        if bookings.iter().any(|&(old_start, old_end)| start < old_end && old_start < end) {
            rejected += 1;
        } else {
            bookings.push((start, end));
            accepted.push(fields[3].to_string());
        }
    }
    println!("{}|rejected={rejected}", accepted.join(","));
}

