import sys


def main():
    lines = sys.stdin.read().splitlines()
    count = int(lines[0])
    room_bookings = {}
    accepted_titles = []
    rejected = 0
    for line in lines[1:1 + count]:
        room, start_text, end_text, title = line.split("|")
        start = int(start_text)
        end = int(end_text)
        bookings = room_bookings.setdefault(room, [])
        overlaps = any(start < existing_end and end > existing_start
