ticket_workflow.source_text:
use std::collections::HashMap;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let n: usize = lines.next().unwrap_or("0").parse().unwrap();
    let mut tickets: HashMap<String, (u8, String)> = HashMap::new();

    for _ in 0..n {
        let mut fields = lines.next().unwrap().split('|');
        let id = fields.next().unwrap().to_string();
        let priority = fields.next().unwrap().parse().unwrap();
        let state = fields.next().unwrap().to_string();
        tickets.insert(id, (priority, state));
    }

    let m: usize = lines.next().unwrap_or("0").parse().unwrap();
    for _ in 0..m {
        let (id, action) = lines.next().unwrap().split_once('|').unwrap();
        if let Some((priority, state)) = tickets.get_mut(id) {
            match action {
                "close" => *state = "closed".to_string(),
                "reopen" => *state = "open".to_string(),
                "escalate" => *priority = (*priority + 1).min(5),
                _ => {}
            }
        }
    }

    let mut open: Vec<(&String, &u8)> = tickets
        .iter()
        .filter(|(_, (_, state))| state == "open")
        .map(|(id, (priority, _))| (id, priority))
        .collect();
    open.sort_by(|(id_a, priority_a), (id_b, priority_b)| {
        priority_b.cmp(priority_a).then_with(|| id_a.cmp(id_b))
    });
    let output = open
        .iter()
        .map(|(id, priority)| format!("{id}:{priority}"))
        .collect::<Vec<_>>()
        .join(",");
    println!("{output}");
}

