sources.access_policy_audit:
use std::collections::HashSet;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let n: usize = lines.next().unwrap_or("0").parse().unwrap();
    let mut policies = HashSet::new();

    for _ in 0..n {
        policies.insert(lines.next().unwrap().to_string());
    }

    let m: usize = lines.next().unwrap_or("0").parse().unwrap();
    let mut output = Vec::new();
    let mut allowed = 0;

    for _ in 0..m {
        let line = lines.next().unwrap();
        let (user, policy) = line.split_once('|').unwrap();
        if policies.contains(policy) {
            allowed += 1;
            output.push(format!("{user}:allow"));
        } else {
            output.push(format!("{user}:deny"));
        }
    }

    output.push(format!("allowed={allowed},denied={}", m - allowed));
    println!("{}", output.join("\n"));
}

