sources.file_backed_notes:
use std::fs;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let title = lines.next().unwrap_or("").to_string();
    let n: usize = lines.next().unwrap_or("0").parse().unwrap();
    let notes: Vec<String> = (0..n)
        .map(|_| lines.next().unwrap_or("").to_string())
        .collect();

    let mut contents = String::new();
    contents.push_str(&title);
    contents.push('\n');
    for note in &notes {
        contents.push_str(note);
        contents.push('\n');
    }
    fs::write("file_backed_notes.txt", contents).unwrap();

    let saved = fs::read_to_string("file_backed_notes.txt").unwrap();
    let mut saved_lines = saved.lines();
    let saved_title = saved_lines.next().unwrap_or("");
    let saved_notes: Vec<&str> = saved_lines.take(n).collect();
    let nonempty = saved_notes.iter().filter(|line| !line.is_empty()).count();
    let characters: usize = saved_notes.iter().map(|line| line.len()).sum();
    println!("{saved_title}|{n}|{nonempty}|{characters}");
}

sources.invoice_rollup:
use std::collections::BTreeMap;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let customer = lines.next().unwrap_or("");
    let n: usize = lines.next().unwrap_or("0").parse().unwrap();
    let mut categories: BTreeMap<String, u128> = BTreeMap::new();
    let mut subtotal = 0u128;

    for _ in 0..n {
        let mut fields = lines.next().unwrap().split('|');
        let category = fields.next().unwrap();
        let quantity: u128 = fields.next().unwrap().parse().unwrap();
        let price: u128 = fields.next().unwrap().parse().unwrap();
        let amount = quantity * price;
        subtotal += amount;
        *categories.entry(category.to_string()).or_insert(0) += amount;
    }

    let totals = categories
        .iter()
        .map(|(category, amount)| format!("{category}:{amount}"))
        .collect::<Vec<_>>()
        .join(",");
    println!("{customer}|{subtotal}|{totals}");
}

