use std::collections::HashMap;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let n: usize = lines.next().unwrap_or("0").parse().unwrap();
    let mut schedules: HashMap<String, Vec<(i128, i128)>> = HashMap::new();
    let mut accepted = Vec::new();
    let mut rejected = 0usize;
    for _ in 0..n {
        let line = lines.next().unwrap();
        let mut fields = line.split('|');
        let room = fields.next().unwrap();
        let start: i128 = fields.next().unwrap().parse().unwrap();
        let end: i128 = fields.next().unwrap().parse().unwrap();
        let title = fields.next().unwrap();
        let room_schedule = schedules.entry(room.to_string()).or_default();
        if room_schedule.iter().any(|&(old_start, old_end)| start < old_end && old_start < end) {
            rejected += 1;
        } else {
            room_schedule.push((start, end));
            accepted.push(title.to_string());
        }
    }
    println!("{}|rejected={}", accepted.join(","), rejected);
}

