use std::collections::HashSet;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let n: usize = lines.next().unwrap_or("0").parse().unwrap();
    let mut policies = HashSet::new();
    for _ in 0..n {
        policies.insert(lines.next().unwrap().to_string());
    }
    let m: usize = lines.next().unwrap_or("0").parse().unwrap();
    let mut output = Vec::new();
    let mut allowed = 0usize;
    for _ in 0..m {
        let line = lines.next().unwrap();
        let mut fields = line.splitn(2, '|');
        let user = fields.next().unwrap();
        let request = fields.next().unwrap();
        if policies.contains(request) {
            allowed += 1;
            output.push(format!("{}:allow", user));
        } else {
            output.push(format!("{}:deny", user));
        }
    }
    output.push(format!("allowed={},denied={}", allowed, m - allowed));
    println!("{}", output.join("\n"));
}

ticket_workflow.source_text:
use std::collections::HashMap;
use std::io::{self, Read};

struct Ticket {
    priority: u8,
    open: bool,
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let n: usize = lines.next().unwrap_or("0").parse().unwrap();
    let mut tickets: HashMap<String, Ticket> = HashMap::new();
    for _ in 0..n {
        let line = lines.next().unwrap();
        let mut fields = line.split('|');
        let id = fields.next().unwrap().to_string();
        let priority: u8 = fields.next().unwrap().parse().unwrap();
        let open = fields.next().unwrap() == "open";
        tickets.insert(id, Ticket { priority, open });
    }
    let m: usize = lines.next().unwrap_or("0").parse().unwrap();
    for _ in 0..m {
        let line = lines.next().unwrap();
        let (id, action) = line.split_once('|').unwrap();
        if let Some(ticket) = tickets.get_mut(id) {
            match action {
                "close" => ticket.open = false,
                "reopen" => ticket.open = true,
                "escalate" => ticket.priority = (ticket.priority + 1).min(5),
                _ => {}
            }
        }
    }
    let mut open_tickets: Vec<_> = tickets.iter().filter(|(_, ticket)| ticket.open).collect();
    open_tickets.sort_by(|(id_a, a), (id_b, b)| b.priority.cmp(&a.priority).then_with(|| id_a.cmp(id_b)));
    println!("{}", open_tickets
        .iter()
        .map(|(id, ticket)| format!("{}:{}", id, ticket.priority))
        .collect::<Vec<_>>()
        .join(","));
}

