source_texts.meeting_schedule:
booking_count = int(input())
accepted_by_room = {}
accepted_titles = []
rejected = 0

for _ in range(booking_count):
    room, start_text, end_text, title = input().split("|", 3)
    start = int(start_text)
    end = int(end_text)
    room_bookings = accepted_by_room.setdefault(room, [])
    overlaps = any(start < booked_end and end > booked_start
                   for booked_start, booked_end in room_bookings)
    if overlaps:
        rejected += 1
    else:
        room_bookings.append((start, end))
        accepted_titles.append(title)

print(f"{','.join(accepted_titles)}|rejected={rejected}")

source_texts.ticket_workflow:
ticket_count = int(input())
tickets = {}
for _ in range(ticket_count):
    ticket_id, priority_text, state = input().split("|", 2)
    tickets[ticket_id] = [int(priority_text), state]

command_count = int(input())
for _ in range(command_count):
    ticket_id, action = input().split("|", 1)
    if ticket_id not in tickets:
        continue
    if action == "close":
        tickets[ticket_id][1] = "closed"
    elif action == "reopen":
        tickets[ticket_id][1] = "open"
    elif action == "escalate":
        tickets[ticket_id][0] = min(5, tickets[ticket_id][0] + 1)

open_tickets = [
    (ticket_id, priority)
    for ticket_id, (priority, state) in tickets.items()
    if state == "open"
]
open_tickets.sort(key=lambda ticket: (-ticket[1], ticket[0]))
print(",".join(f"{ticket_id}:{priority}" for ticket_id, priority in open_tickets))

