source_texts.file_backed_notes:
use std::fs;
use std::io::{self, BufRead, Write};

fn read_line<R: BufRead>(reader: &mut R) -> String {
    let mut line = String::new();
    reader.read_line(&mut line).unwrap();
    if line.ends_with('\n') {
        line.pop();
        if line.ends_with('\r') {
            line.pop();
        }
    }
    line
}

fn main() {
    let stdin = io::stdin();
    let mut reader = stdin.lock();
    let title = read_line(&mut reader);
    let n: usize = read_line(&mut reader).parse().unwrap();
    let notes: Vec<String> = (0..n).map(|_| read_line(&mut reader)).collect();

    let mut file = fs::File::create("file_backed_notes.txt").unwrap();
    writeln!(file, "{}", title).unwrap();
    for note in &notes {
        writeln!(file, "{}", note).unwrap();
    }
    drop(file);

    let contents = fs::read_to_string("file_backed_notes.txt").unwrap();
