use std::collections::HashMap;
use std::io::{self, BufRead};

fn line<R: BufRead>(r: &mut R) -> String {
    let mut s = String::new();
    r.read_line(&mut s).unwrap();
    s.trim_end_matches(['\r', '\n']).to_string()
}

fn main() {
    let stdin = io::stdin();
    let mut r = stdin.lock();
    let n: usize = line(&mut r).parse().unwrap();
    let mut tickets: HashMap<String, (u8, String)> = HashMap::new();
    for _ in 0..n {
        let s = line(&mut r);
        let mut parts = s.split('|');
        let id = parts.next().unwrap().to_string();
        let priority = parts.next().unwrap().parse().unwrap();
        let state = parts.next().unwrap().to_string();
        tickets.insert(id, (priority, state));
    }
    let m: usize = line(&mut r).parse().unwrap();
    for _ in 0..m {
        let s = line(&mut r);
        let (id, action) = s.split_once('|').unwrap();
        if let Some((priority, state)) = tickets.get_mut(id) {
            match action {
                "close" => *state = "closed".to_string(),
                "reopen" => *state = "open".to_string(),
                "escalate" => *priority = (*priority + 1).min(5),
                _ => {}
            }
        }
    }
    let mut open: Vec<_> = tickets.iter().filter(|(_, (_, state))| state == "open").collect();
    open.sort_by(|(id_a, (priority_a, _)), (id_b, (priority_b, _))| priority_b.cmp(priority_a).then_with(|| id_a.cmp(id_b)));
    println!("{}", open.iter().map(|(id, (priority, _))| format!("{}:{}", id, priority)).collect::<Vec<_>>().join(","));
}

