    let stored_notes: Vec<&str> = lines.take(n).collect();
    let nonempty = stored_notes.iter().filter(|line| !line.is_empty()).count();
    let characters: usize = stored_notes.iter().map(|line| line.chars().count()).sum();
    println!("{}|{}|{}|{}", stored_title, n, nonempty, characters);
}

sources.invoice_rollup:
use std::collections::BTreeMap;
use std::io::{self, BufRead};

fn line<R: BufRead>(r: &mut R) -> String {
    let mut s = String::new();
    r.read_line(&mut s).unwrap();
    s.trim_end_matches(['\r', '\n']).to_string()
}

fn main() {
    let stdin = io::stdin();
    let mut r = stdin.lock();
    let customer = line(&mut r);
    let n: usize = line(&mut r).parse().unwrap();
    let mut categories: BTreeMap<String, u128> = BTreeMap::new();
    let mut subtotal: u128 = 0;
    for _ in 0..n {
        let s = line(&mut r);
        let mut parts = s.split('|');
        let category = parts.next().unwrap();
        let quantity: u128 = parts.next().unwrap().parse().unwrap();
        let price: u128 = parts.next().unwrap().parse().unwrap();
        let amount = quantity * price;
        subtotal += amount;
        *categories.entry(category.to_string()).or_default() += amount;
    }
    let totals = categories.iter().map(|(category, amount)| format!("{}:{}", category, amount)).collect::<Vec<_>>().join(",");
    println!("{}|{}|{}", customer, subtotal, totals);
}

sources.meeting_schedule:
use std::collections::HashMap;
use std::io::{self, BufRead};

fn line<R: BufRead>(r: &mut R) -> String {
    let mut s = String::new();
    r.read_line(&mut s).unwrap();
    s.trim_end_matches(['\r', '\n']).to_string()
}

fn main() {
    let stdin = io::stdin();
    let mut r = stdin.lock();
    let n: usize = line(&mut r).parse().unwrap();
    let mut rooms: HashMap<String, Vec<(i64, i64)>> = HashMap::new();
    let mut accepted = Vec::new();
    let mut rejected = 0;
    for _ in 0..n {
        let s = line(&mut r);
        let mut parts = s.splitn(4, '|');
        let room = parts.next().unwrap();
        let start: i64 = parts.next().unwrap().parse().unwrap();
        let end: i64 = parts.next().unwrap().parse().unwrap();
        let title = parts.next().unwrap();
        let bookings = rooms.entry(room.to_string()).or_default();
        if bookings.iter().all(|&(old_start, old_end)| end <= old_start || start >= old_end) {
            bookings.push((start, end));
            accepted.push(title.to_string());
        } else {
            rejected += 1;
        }
    }
    println!("{}|rejected={}", accepted.join(","), rejected);
}

sources.shipment_state:
use std::collections::BTreeMap;
use std::io::{self, BufRead};

fn line<R: BufRead>(r: &mut R) -> String {
    let mut s = String::new();
    r.read_line(&mut s).unwrap();
    s.trim_end_matches(['\r', '\n']).to_string()
}

fn main() {
    let stdin = io::stdin();
    let mut r = stdin.lock();
    let n: usize = line(&mut r).parse().unwrap();
    let mut shipments = BTreeMap::new();
    for _ in 0..n {
        let s = line(&mut r);
        let (id, state) = s.split_once('|').unwrap();
        shipments.insert(id.to_string(), state.to_string());
    }
    let m: usize = line(&mut r).parse().unwrap();
    let mut invalid = 0;
    for _ in 0..m {
        let s = line(&mut r);
        let (id, action) = s.split_once('|').unwrap();
        if let Some(state) = shipments.get_mut(id) {
            let next = match (state.as_str(), action) {
                ("created", "pack") => Some("packed"),
                ("packed", "ship") => Some("shipped"),
                ("shipped", "deliver") => Some("delivered"),
                _ => None,
            };
            if let Some(next) = next {
                *state = next.to_string();
            } else {
                invalid += 1;
            }
        } else {
            invalid += 1;
        }
    }
    let output = shipments.iter().map(|(id, state)| format!("{}:{}", id, state)).collect::<Vec<_>>().join(",");
    println!("{}|invalid={}", output, invalid);
}

sources.ticket_workflow:
use std::collections::HashMap;
use std::io::{self, BufRead};

fn line<R: BufRead>(r: &mut R) -> String {
    let mut s = String::new();
    r.read_line(&mut s).unwrap();
    s.trim_end_matches(['\r', '\n']).to_string()
}

fn main() {
    let stdin = io::stdin();
    let mut r = stdin.lock();
    let n: usize = line(&mut r).parse().unwrap();
    let mut tickets: HashMap<String, (u8, String)> = HashMap::new();
    for _ in 0..n {
        let s = line(&mut r);
        let mut parts = s.split('|');
        let id = parts.next().unwrap().to_string();
        let priority = parts.next().unwrap().parse().unwrap();
        let state = parts.next().unwrap().to_string();
        tickets.insert(id, (priority, state));
    }
    let m: usize = line(&mut r).parse().unwrap();
    for _ in 0..m {
        let s = line(&mut r);
        let (id, action) = s.split_once('|').unwrap();
        if let Some((priority, state)) = tickets.get_mut(id) {
            match action {
                "close" => *state = "closed".to_string(),
                "reopen" => *state = "open".to_string(),
                "escalate" => *priority = (*priority + 1).min(5),
                _ => {}
            }
        }
    }
    let mut open: Vec<_> = tickets.iter().filter(|(_, (_, state))| state == "open").collect();
    open.sort_by(|(id_a, (priority_a, _)), (id_b, (priority_b, _))| priority_b.cmp(priority_a).then_with(|| id_a.cmp(id_b)));
    println!("{}", open.iter().map(|(id, (priority, _))| format!("{}:{}", id, priority)).collect::<Vec<_>>().join(","));
}

