            rejected += 1
        else:
            room_bookings.append((start, end))
            accepted.append(title)

    print(f"{','.join(accepted)}|rejected={rejected}")


if __name__ == "__main__":
    main()

source_texts.ticket_workflow:
import sys


def main():
    lines = sys.stdin.read().splitlines()
    pos = 0
    count = int(lines[pos])
    pos += 1
    tickets = {}
    for _ in range(count):
        ticket_id, priority, state = lines[pos].split("|", 2)
        pos += 1
        tickets[ticket_id] = [int(priority), state]

    command_count = int(lines[pos])
    pos += 1
    for _ in range(command_count):
        ticket_id, action = lines[pos].split("|", 1)
        pos += 1
        ticket = tickets.get(ticket_id)
        if ticket is None:
            continue
        if action == "close":
            ticket[1] = "closed"
        elif action == "reopen":
            ticket[1] = "open"
        elif action == "escalate":
            ticket[0] = min(5, ticket[0] + 1)

    open_tickets = [
        (ticket_id, priority)
        for ticket_id, (priority, state) in tickets.items()
        if state == "open"
    ]
    open_tickets.sort(key=lambda item: (-item[1], item[0]))
    print(",".join(f"{ticket_id}:{priority}"
                   for ticket_id, priority in open_tickets))


if __name__ == "__main__":
    main()

