        subtotal += amount;
        *categories.entry(category).or_default() += amount;
    }
    let rollup = categories.iter().map(|(category, amount)| format!("{}:{}", category, amount)).collect::<Vec<_>>().join(",");
    println!("{}|{}|{}", customer, subtotal, rollup);
}

