use std::collections::HashSet;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let n: usize = lines.next().unwrap_or("0").trim().parse().unwrap();
    let mut policies: HashSet<(String, String, String)> = HashSet::new();
    for _ in 0..n {
        let mut fields = lines.next().unwrap().splitn(3, '|');
        policies.insert((
            fields.next().unwrap().to_string(),
            fields.next().unwrap().to_string(),
            fields.next().unwrap().to_string(),
        ));
    }
    let m: usize = lines.next().unwrap_or("0").trim().parse().unwrap();
    let mut output = Vec::new();
    let mut allowed = 0usize;
    for _ in 0..m {
        let mut fields = lines.next().unwrap().splitn(4, '|');
        let user = fields.next().unwrap();
        let role = fields.next().unwrap();
        let resource = fields.next().unwrap();
        let action = fields.next().unwrap();
        let is_allowed = policies.contains(&(role.to_string(), resource.to_string(), action.to_string()));
        if is_allowed {
            allowed += 1;
        }
        output.push(format!("{}:{}", user, if is_allowed { "allow" } else { "deny" }));
    }
    output.push(format!("allowed={},denied={}", allowed, m - allowed));
    println!("{}", output.join("\n"));
}

