use std::collections::HashMap;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let n: usize = lines.next().unwrap_or("0").trim().parse().unwrap();
    let mut rooms: HashMap<String, Vec<(i64, i64)>> = HashMap::new();
    let mut accepted = Vec::new();
    let mut rejected = 0usize;
    for _ in 0..n {
        let mut fields = lines.next().unwrap().splitn(4, '|');
        let room = fields.next().unwrap().to_string();
        let start: i64 = fields.next().unwrap().parse().unwrap();
        let end: i64 = fields.next().unwrap().parse().unwrap();
        let title = fields.next().unwrap().to_string();
        let bookings = rooms.entry(room).or_default();
        if bookings.iter().any(|&(old_start, old_end)| start < old_end && old_start < end) {
            rejected += 1;
        } else {
            bookings.push((start, end));
            accepted.push(title);
        }
    }
    println!("{}|rejected={}", accepted.join(","), rejected);
}

