use std::collections::HashMap;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let n: usize = lines.next().unwrap_or("0").trim().parse().unwrap();
    let mut tickets: HashMap<String, (u8, bool)> = HashMap::new();
    for _ in 0..n {
        let mut fields = lines.next().unwrap().splitn(3, '|');
        let id = fields.next().unwrap().to_string();
        let priority: u8 = fields.next().unwrap().parse().unwrap();
        let open = fields.next().unwrap() == "open";
        tickets.insert(id, (priority, open));
    }
    let m: usize = lines.next().unwrap_or("0").trim().parse().unwrap();
    for _ in 0..m {
        let (id, action) = lines.next().unwrap().split_once('|').unwrap();
        if let Some((priority, open)) = tickets.get_mut(id) {
            match action {
                "close" => *open = false,
                "reopen" => *open = true,
                "escalate" => *priority = (*priority + 1).min(5),
                _ => {}
            }
        }
    }
    let mut open: Vec<(&String, &u8)> = tickets
        .iter()
        .filter_map(|(id, (priority, is_open))| is_open.then_some((id, priority)))
        .collect();
    open.sort_by(|(id_a, priority_a), (id_b, priority_b)| {
        priority_b.cmp(priority_a).then_with(|| id_a.cmp(id_b))
    });
    println!("{}", open.iter().map(|(id, priority)| format!("{}:{}", id, priority)).collect::<Vec<_>>().join(","));
}

